1	import { AtelierAmbience } from './atelier/AtelierAmbience';
2	import React, { useEffect, useRef, useState } from 'react';
3	import type { PresentationState, PresentationView } from '../services/presentation';
4	import { AtelierScene, type ConversationPhase } from './atelier/AtelierScene';
5	import './ReadingStage.css';
6	
7	interface ReadingStageProps {
8	  accountUid: string;
9	  extraControls?:React.ReactNode;
10	  chartTools?:React.ReactNode;
11	  presentation: PresentationState;
12	  phase: ConversationPhase;
13	  paused: boolean;
14	  onPause: (paused: boolean) => void;
15	  onView: (view: PresentationView) => void;
16	  chart: React.ReactNode;
17	  conversation: React.ReactNode;
18	}
19	
20	export function ReadingStage({ chartTools, extraControls, accountUid, presentation, phase, paused, onPause, onView, chart, conversation }: ReadingStageProps) {
21	  const visual = useRef<HTMLDivElement>(null);
22	  const [inset,setInset]=useState({x:1,y:1});
23	  const [dragging,setDragging]=useState(false);
24	  const insetRef=useRef(inset);
25	  const drag=useRef<{pointer:number;clientX:number;clientY:number;x:number;y:number;rangeX:number;rangeY:number}|null>(null);
26	  const clamp=(value:number)=>Math.max(0,Math.min(1,value));
27	  const place=(position:{x:number;y:number},save=true)=>{
28	    const next={x:clamp(position.x),y:clamp(position.y)};insetRef.current=next;setInset(next);
29	    if(save)try{localStorage.setItem('natally.inset-position.'+accountUid,JSON.stringify(next));}catch{/* Position still works for this appointment. */}
30	  };
31	  useEffect(()=>{try{const saved=JSON.parse(localStorage.getItem('natally.inset-position.'+accountUid)||'null');place(saved&&Number.isFinite(saved.x)&&Number.isFinite(saved.y)?saved:{x:1,y:1},false);}catch{place({x:1,y:1},false);}},[accountUid]);
32	  useEffect(()=>{const move=(event:Event)=>{
33	    const detail=(event as CustomEvent<{x:number;y:number;bounds?:{left:number;top:number;right:number;bottom:number}}>).detail;if(!Number.isFinite(detail?.x)||!Number.isFinite(detail?.y)||!visual.current||drag.current)return;
34	    const position=insetRef.current,rect=visual.current.getBoundingClientRect();
35	    const left=(12+position.x*(rect.width*.66-24))/rect.width,top=(8+position.y*(rect.height*.66-44))/rect.height;
36	    const bounds=detail.bounds||{left:detail.x-100,right:detail.x+100,top:detail.y-80,bottom:detail.y+80};
37	    if(bounds.right/2048>=left-.02&&bounds.left/2048<=left+.36&&bounds.bottom/1280>=top-.02&&bounds.top/1280<=top+.36)place({x:detail.x>1024?0:1,y:detail.bounds?(detail.y>640?0:1):position.y});
38	  };window.addEventListener('natally-atelier-shelf-focus',move);return()=>window.removeEventListener('natally-atelier-shelf-focus',move);},[accountUid]);
39	  const endDrag=(event:React.PointerEvent<HTMLButtonElement>)=>{
40	    if(!drag.current)return;drag.current=null;setDragging(false);
41	    if(event.currentTarget.hasPointerCapture(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);
42	    const snap=(value:number)=>value<.09?0:value>.91?1:value;
43	    place({x:snap(insetRef.current.x),y:snap(insetRef.current.y)});
44	  };
45	  const insetStyle={'--inset-left':`calc(${inset.x*66}% + ${12-inset.x*24}px)`,'--inset-top':`calc(${inset.y*66}% + ${8-inset.y*44}px)`} as React.CSSProperties;
46	  const chartPane = useRef<HTMLDivElement>(null);
47	  const roomPane = useRef<HTMLDivElement>(null);
48	  const [reducedMotion, setReducedMotion] = useState(false);
49	  useEffect(() => {
50	    const media = window.matchMedia('(prefers-reduced-motion: reduce)');
51	    const update = () => setReducedMotion(media.matches);
52	    update(); media.addEventListener('change', update);
53	    return () => media.removeEventListener('change', update);
54	  }, []);
55	  useEffect(() => {
56	    chartPane.current?.removeAttribute('inert');
57	    roomPane.current?.toggleAttribute('inert', presentation.view !== 'atelier');
58	  }, [presentation.view]);
59	  const inRoom = presentation.view === 'atelier';
60	  return <section className="reading-stage" style={insetStyle} data-dragging={dragging} data-view={presentation.view} data-reduced-motion={reducedMotion} aria-label="A moment with Natally">
61	    <AtelierAmbience key={accountUid} view={presentation.view} phase={phase} />
62	    <div className="reading-stage__layout">
63	      <div className="reading-stage__visual" ref={visual}>
64	        <div className="reading-stage__pane reading-stage__room" data-active={inRoom}>
65	          <div ref={roomPane} className="reading-stage__content" aria-hidden={!inRoom}>
66	            <AtelierScene accountUid={accountUid} phase={phase} motionEnabled={!paused && !reducedMotion} sceneVisible />
67	          </div>
68	          {!inRoom && <button className="reading-stage__inset-focus" onClick={() => onView('atelier')} aria-label="Bring Natally's reading room into focus"><span>Natally <b>↗ Bring into focus</b></span></button>}
69	        </div>
70	        <div className="reading-stage__pane reading-stage__chart" data-active={!inRoom} data-chart-callout-boundary data-chart-inset={inRoom}>
71	          <div ref={chartPane} className="reading-stage__content">{chart}</div>
72	        </div>
73	        <button type="button" className="reading-stage__inset-handle" aria-label="Move inset card" title="Drag anywhere in the scene; release near an edge to dock. Arrow keys move; Home docks top left, End bottom right."
74	          onPointerDown={event=>{if(event.button!==0||!visual.current)return;const rect=visual.current.getBoundingClientRect();event.preventDefault();event.currentTarget.focus();event.currentTarget.setPointerCapture(event.pointerId);drag.current={pointer:event.pointerId,clientX:event.clientX,clientY:event.clientY,...insetRef.current,rangeX:Math.max(1,rect.width*.66-24),rangeY:Math.max(1,rect.height*.66-44)};setDragging(true);}}
75	          onPointerMove={event=>{const start=drag.current;if(!start||start.pointer!==event.pointerId)return;place({x:start.x+(event.clientX-start.clientX)/start.rangeX,y:start.y+(event.clientY-start.clientY)/start.rangeY},false);}}
76	          onPointerUp={endDrag} onPointerCancel={endDrag}
77	          onKeyDown={event=>{const step=event.shiftKey?.1:.025;const directions:Record<string,[number,number]>={ArrowLeft:[-step,0],ArrowRight:[step,0],ArrowUp:[0,-step],ArrowDown:[0,step]};if(directions[event.key]){event.preventDefault();const [x,y]=directions[event.key];place({x:inset.x+x,y:inset.y+y});}else if(event.key==='Home'||event.key==='End'){event.preventDefault();place(event.key==='Home'?{x:0,y:0}:{x:1,y:1});}}}>⠿ <span>Move {inRoom?'chart':'Natally'}</span></button>
78	        <div className="reading-stage__view-note">Chart highlights follow Natally’s reading</div>
79	      </div>
80	      <div className="reading-stage__controls" role="group" aria-label="Reading view and motion">
81	        {extraControls}
82	        <button type="button" onClick={() => onView(inRoom ? 'chart' : 'atelier')}>{inRoom ? 'Your chart' : 'Reading room'}</button>
83	        <button type="button" aria-pressed={paused} onClick={() => onPause(!paused)}>{paused ? 'Resume motion' : 'Pause motion'}</button>
84	      </div>
85	      <div className="reading-stage__conversation">{conversation}</div>
86	    </div>
87	    {!inRoom && chartTools}
88	  </section>;
89	}
