74	const LORE_STORAGE_KEY = 'astrosphere_user_lore_v1';
75	
76	export default function App() {
77	  const [showLearning,setShowLearning]=useState(false);
78	  const [quickReadingBusy,setQuickReadingBusy]=useState(false);
79	  const quickReadingLock=useRef(false);
80	  const [quickReadingError,setQuickReadingError]=useState<string|null>(null);
81	  const [chartInput, setChartInput] = useState<NatalChartInput | null>(null);
82	  const [chartResult, setChartResult] = useState<NatalChartResult | null>(null);
83	  const [readingObservation,setReadingObservation] = useState<{chart:NatalChartResult;archived:boolean}|null>(null);
84	  const readingObservationRef = useRef<typeof readingObservation>(null);
85	  const displayedChart = readingObservation && chartResult && chartFocusKeyMatches(chartFocusKey(readingObservation.chart),chartResult) ? readingObservation.chart : chartResult;
86	  useEffect(() => {readingObservationRef.current=null;setReadingObservation(null);},[chartResult]);
87	  const [wisdom, setWisdom] = useState<NumerologyAndThemes | null>(null);
88	  const [isCalculating, setIsCalculating] = useState<boolean>(false);
89	  const [currentSkyError, setCurrentSkyError] = useState<string | null>(null);
90	  const [isRefreshingSky, setIsRefreshingSky] = useState(false);
91	  const skyOperation = useRef(0);
92	  const [onboardBusy, setOnboardBusy] = useState<boolean>(false);
93	  const [onboardError, setOnboardError] = useState<string | null>(null);
94	  const [isSpinning, setIsSpinning] = useState<boolean>(true);
95	  const [resetTrigger, setResetTrigger] = useState<number>(0);
96	  const [inspectorTab, setInspectorTab] = useState<'planets' | 'houses'>('planets');
97	  const [isInspectorCollapsed, setIsInspectorCollapsed] = useState<boolean>(true);
98	
99	  // Multi-Selection State for Shift-/Ctrl-Clicking Components
100	  const [presentation, setPresentation] = useState(() => initialPresentation(''));
101	  const [focusReadingRequest, setFocusReadingRequest] = useState(0);
102	  const selectedComponents = presentation.selectedTargets;
103	  const setSelectedComponents = (value: string[] | ((previous:string[])=>string[])) => setPresentation(previous => ({...previous,selectedTargets:typeof value === 'function' ? value(previous.selectedTargets) : value}));
104	  const chartRef = useRef(chartResult); chartRef.current = chartResult;
105	  const [selectionRequest, setSelectionRequest] = useState<{id:string;targets:string[];sourceChart:NatalChartResult} | null>(null);
106	  const [educationalRequest, setEducationalRequest] = useState<{id:string;target:string;sourceChart:NatalChartResult} | null>(null);
107	  const [phase, setPhase] = useState<'idle'|'listening'|'thinking'|'speaking'>('idle');
108	  const [motionPaused, setMotionPaused] = useState(false);
109	  const handleReadingChart = useCallback((source:NatalChartResult,archived:boolean) => {
110	    if (!chartRef.current || !chartFocusKeyMatches(chartFocusKey(source),chartRef.current)) return;
111	    const observation={chart:source,archived};
112	    readingObservationRef.current=observation;setReadingObservation(observation);
113	    // Manual inspection lasts until the next reading or replay begins.
114	    setPresentation(previous => ({...previous,follow:true,panel:'conversation'}));
115	  },[]);
116	  const handlePresentationAction = useCallback((action:PresentationAction, sourceChart:NatalChartResult) => {
117	    if (!chartRef.current || !chartFocusKeyMatches(chartFocusKey(sourceChart),chartRef.current)) return;
118	    setPresentation(previous => reducePresentation(previous,action,sourceChart));
119	  }, []);
120	  const handleChartFocus = useCallback((targets:string[], sourceChart:NatalChartResult) => {
121	    if (chartRef.current !== sourceChart) return;
122	    setPresentation(previous => reducePresentation(previous,targets.length ? {type:'focus',targets:targets.slice(0,6)} : {type:'clear'},sourceChart));
123	  }, []);
124	  const setManualView = (view:PresentationView) => setPresentation(previous => ({...previous,view,follow:false}));
125	  const showTargets = (targets:string[]) => {
126	    const source=readingObservationRef.current?.chart ?? chartResult;
127	    if (!source) return;
128	    const canonical = targets.map(target => resolveChartTarget(target,source)).filter((target):target is string => !!target);
129	    if (!canonical.length) return;
130	    setPresentation(previous => ({...reducePresentation(previous,{type:'focus',targets:canonical.slice(0,6)},source),selectedTargets:[...new Set([...previous.selectedTargets,...canonical])],view:'chart',follow:false,panel:'selection'}));
131	  };
132	  const [isGeneratingMultiReading, setIsGeneratingMultiReading] = useState(false);
133	  const [isNatalParamsRolledUp, setIsNatalParamsRolledUp] = useState(true);
134	  const [isThemesRolledUp, setIsThemesRolledUp] = useState(false);
135	
136	  // Natally Companion State
137	  const [isChatOpen, setIsChatOpen] = useState(true);
138	  const [synastryChart, setSynastryChart] = useState<NatalChartResult | null>(null);
139	  const [voiceSettings, setVoiceSettings] = useState<VoiceSettings>(() => loadVoiceSettings());
140	  const [isSpeaking, setIsSpeaking] = useState(false);
141	  const [speechSnippet, setSpeechSnippet] = useState<string | null>(null);
142	  const [activeTargetEntity, setActiveTargetEntity] = useState<string | null>(null);
143	  // Keyboard quick-entry: typing anything (no field focused) summons a small
144	  // chat entry box — mouseless desktop path that never blocks the torus view.
145	  const [quickEntryOpen, setQuickEntryOpen] = useState<boolean>(false);
146	  const [quickMessage, setQuickMessage] = useState<{ text: string; nonce: number } | null>(null);
147	  const [externalReadingToInject, setExternalReadingToInject] = useState<{
148	    streamId?: string;
149	    model?: string;
150	    title: string;
151	    content: string;
152	    type: string;
153	    sender?: 'user' | 'natally';
154	    observationSnapshot?: NatalChartResult['currentSky'];
155	    generatedAt?:string;
156	    chartCues?: ChartCue[];
157	    presentationVersion?:1;
158	    presentationCues?:PresentationCue[];
159	    chartFocusKey?: string;
160	  } | null>(null);
161	  const [externalReadingProgress,setExternalReadingProgress] = useState<{id:string;text:string;model?:string;chart:NatalChartResult;title:string;error?:string}|null>(null);
162	
163	  // Modals
164	  const [showExportModal, setShowExportModal] = useState(false);
165	  const [showAuthModal, setShowAuthModal] = useState(false);
166	  const [accountBillingOpen,setAccountBillingOpen] = useState(false);
167	  const [showReadingsModal, setShowReadingsModal] = useState(false);
168	  const [readingsInitialType, setReadingsInitialType] = useState<
169	    'horoscope' | 'synastry' | 'house' | 'planet' | 'aspect'
170	  >('horoscope');
171	  const [readingsTargetKey, setReadingsTargetKey] = useState<string | undefined>(undefined);
172	
173	  // User state & Persistent Lore memory store
174	  const [user, setUser] = useState<FirebaseUser | null>(null);
175	  useEffect(() => { setEducationalRequest(null); }, [chartResult, user?.uid]);
176	  const atelierTheme=useAtelierTheme(user?.uid??null);
177	  useEffect(()=>{quickReadingLock.current=false;setQuickReadingBusy(false);setQuickReadingError(null);setShowLearning(false);setAccountBillingOpen(false);},[user?.uid]);
178	  const [authResolved, setAuthResolved] = useState<boolean>(false);
179	  const [profileState, setProfileState] = useState<SessionProfileState<NatalChartInput>>({ uid: null, status: 'loading', profile: null, error: null });
180	  const profileLoader = useRef<ReturnType<typeof createSessionProfileLoader<NatalChartInput>> | null>(null);
181	  const sessionGeneration = useRef(0);
182	  const booted = useRef(false);
183	  // Billing/quota storage failure: proceeding unmetered would leak funds.
184	  const [storageBillingBlocked, setStorageBillingBlocked] = useState<string | null>(null);
185	  const [userLore, setUserLore] = useState<string[]>([]);
186	  const [historyRevision, setHistoryRevision] = useState(0);
187	  // This closure belongs to one authenticated session, including A→B→A changes.
188	  const renderGeneration = sessionGeneration.current;
189	  const isCurrentSession = () => !!user && auth.currentUser?.uid === user.uid &&
190	    sessionGeneration.current === renderGeneration && !isNatallyHistoryErasing(user.uid);
191	
192	  useEffect(() => {
193	    const changed = (event: Event) => {
194	      const notice = (event as CustomEvent<HistoryErasureNotice>).detail;
195	      if (notice.accountUid !== auth.currentUser?.uid) return;
196	      sessionGeneration.current++;
197	      stopSpeaking(); setIsSpeaking(false); setSpeechSnippet(null); setPhase('idle');
198	      setShowReadingsModal(false); setExternalReadingToInject(null); setExternalReadingProgress(null); setQuickMessage(null);
199	      setSelectionRequest(null); setIsGeneratingMultiReading(false);
200	      if (notice.phase === 'complete') {
201	        booted.current = false;
202	        skyOperation.current++;
203	        chartRef.current = null;
204	        setChartInput(null); setChartResult(null); setWisdom(null); setSynastryChart(null);
205	        setCurrentSkyError(null); setIsRefreshingSky(false); setIsCalculating(false);
206	        setReadingObservation(null); readingObservationRef.current = null;
207	        setSelectedComponents([]); setActiveTargetEntity(null); setPresentation(initialPresentation(''));
208	        setOnboardError(null); setOnboardBusy(false); setShowAuthModal(false); setShowExportModal(false);
209	        setProfileState({ uid: notice.accountUid, status: 'ready', profile: null, error: null });
210	      }
211	      if (notice.phase !== 'erasing') {
212	        const saved = loadAccountValue<unknown>(LORE_STORAGE_KEY, notice.accountUid, []);
213	        setUserLore(Array.isArray(saved) ? saved.filter((value): value is string => typeof value === 'string') : []);
214	        setHistoryRevision(value => value + 1);
215	      }
216	    };
217	    window.addEventListener(HISTORY_ERASURE_EVENT, changed);
218	    return () => window.removeEventListener(HISTORY_ERASURE_EVENT, changed);
219	  }, []);
220	
221	  useEffect(() => {
222	    if (isCurrentSession()) saveAccountValue(LORE_STORAGE_KEY, user!.uid, userLore);
223	  }, [userLore, user]);
224	
225	  useEffect(() => {
226	    if (!authResolved || !user || profileState.status !== 'ready' || !chartInput) return;
227	    const onAnyKey = (e: KeyboardEvent) => {
228	      if (document.querySelector('dialog[open]') || (e.target as HTMLElement | null)?.closest('button, a, [role="button"]')) return;
229	      if (e.key === 'Escape') { setQuickEntryOpen(false); return; }
230	      const target = e.target as HTMLElement | null;
231	      const inField = target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT' || target.isContentEditable);
232	      const printable = e.key.length === 1 || e.key === 'Backspace' || e.key === 'Enter';
233	      if (!inField && !quickEntryOpen && printable && !e.ctrlKey && !e.metaKey && !e.altKey) {
234	        setQuickEntryOpen(true);
235	      }
236	    };
237	    window.addEventListener('keydown', onAnyKey);
238	    return () => window.removeEventListener('keydown', onAnyKey);
239	  }, [quickEntryOpen, authResolved, user, profileState.status, chartInput]);
240	
241	  useEffect(() => {
242	    const loader = createSessionProfileLoader<NatalChartInput>(async uid => {
243	      if (requiresFreshOnboarding(uid)) return null;
244	      const remote = await fetchUserIntake(uid);
245	      return requiresFreshOnboarding(uid) ? null : remote ?? loadNatalIntake(uid);
246	    }, state => {
247	      const restartRequired = !!state.uid && requiresFreshOnboarding(state.uid);
248	      if (restartRequired && state.status === 'ready') state = { ...state, profile: null };
249	      setProfileState(state);
250	      if (state.status === 'ready' && state.uid && auth.currentUser?.uid === state.uid) {
251	        if (state.profile) saveNatalIntake(state.profile, state.uid);
252	        setChartInput(state.profile);
253	      }
254	    });
255	    profileLoader.current = loader;
256	    const unsubscribe = onAuthStateChanged(auth, currentUser => {
257	      sessionGeneration.current += 1;
258	      booted.current = false;
259	      stopSpeaking();
260	      setIsSpeaking(false);
261	      setSpeechSnippet(null);
262	      setActiveTargetEntity(null);
263	      setSelectedComponents([]);
264	      setPresentation(initialPresentation('')); setSelectionRequest(null); setPhase('idle');
265	      setIsGeneratingMultiReading(false);
266	      const lore = loadAccountValue<unknown>(LORE_STORAGE_KEY, currentUser?.uid, []);
267	      setUserLore(Array.isArray(lore) ? lore.filter((item): item is string => typeof item === 'string') : []);
268	      setUser(currentUser);
269	      setAuthResolved(true);
270	      setChartInput(null);
271	      setChartResult(null);
272	      setCurrentSkyError(null);
273	      setIsRefreshingSky(false);
274	      skyOperation.current += 1;
275	      setWisdom(null);
276	      setSynastryChart(null);
277	      setStorageBillingBlocked(null);
278	      setOnboardError(null);
279	      setOnboardBusy(false);
280	      setIsCalculating(false);
281	      setIsChatOpen(true);
282	      setQuickEntryOpen(false);
283	      setQuickMessage(null);
284	        setExternalReadingToInject(null);setExternalReadingProgress(null);
285	      setShowAuthModal(false);
286	      setShowReadingsModal(false);
287	      setShowExportModal(false);
288	      void loader.load(currentUser?.uid ?? null);
289	    }, () => {
290	      sessionGeneration.current += 1;
291	      stopSpeaking();
292	      setUserLore([]);
293	      setChartInput(null);
