81	function uniqueNudgeMessages(messages: PersistentChatMessage[]): PersistentChatMessage[] {
82	  const ids = new Set<string>(), texts = new Set<string>();
83	  return messages.filter(message => {
84	    if (!message.authoredNudgeId) return true;
85	    const text = normalizeLoreText(message.text);
86	    if (ids.has(message.authoredNudgeId) || texts.has(text)) return false;
87	    ids.add(message.authoredNudgeId);texts.add(text);return true;
88	  });
89	}
