150	function validatedObservationSnapshot(snapshot: NatalChartResult['currentSky']): NatalChartResult['currentSky'] {
151	  if (!snapshot || typeof snapshot.observedAt !== 'string' || !Number.isFinite(Date.parse(snapshot.observedAt)) ||
152	      !Array.isArray(snapshot.bodies) || !snapshot.bodies.every(body => !!body && typeof body.target === 'string' && body.target.endsWith(' @ '+snapshot.observedAt) && Number.isFinite(body.lon)) ||
153	      !Array.isArray(snapshot.aspects) || !snapshot.aspects.every(aspect => !!aspect && typeof aspect.name === 'string' && typeof aspect.from === 'string' && typeof aspect.to === 'string' && Number.isFinite(aspect.orb))) return undefined;
154	  const {observationContext:context,...positions} = snapshot;
155	  const validContext = !!context && typeof context === 'object' && !Array.isArray(context) && typeof context.timezoneId === 'string' &&
